package com.smartinternship.controller; import com.smartinternship.model.InternshipOffer; import com.smartinternship.repository.InternshipOfferRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/offers") public class OfferController { private final InternshipOfferRepository r; public OfferController(InternshipOfferRepository r){this.r=r;} @GetMapping public List<InternshipOffer> all(){return r.findAll();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public InternshipOffer create(@Valid @RequestBody InternshipOffer o){return r.save(o);} }